CREATE SCHEMA app;
CREATE TYPE app.user_status AS ENUM ('active', 'on-hold', 'closed');
CREATE DOMAIN app.email AS text CHECK (VALUE LIKE '%@%');
CREATE TYPE app.address AS (street text, zip varchar(10));
CREATE TABLE app.users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email app.email NOT NULL UNIQUE,
  status app.user_status NOT NULL,
  manager_id bigint REFERENCES app.users (id),
  balance numeric(12, 2) NOT NULL DEFAULT 0,
  tags text[] NOT NULL DEFAULT '{}',
  home app.address,
  type text,
  created_at timestamptz NOT NULL DEFAULT now(),
  -- @go.type github.com/acme/doc.Profile
  profile jsonb,
  doubled bigint GENERATED ALWAYS AS (id * 2) STORED
);
